INSERT INTO askdata_tool_config (id,tool_name,tool_display_name,description,api_url,http_method,content_type,required_role,dept_filter,is_sensitive,is_enabled,auth_config_id,response_data_path,response_chart_type,response_total_path,response_schema,timeout_seconds,cache_ttl_seconds,created_by,created_at,updated_by,updated_at,version) VALUES
(1,'get_sales_report','销售报表查询','查询销售报表数据，支持按地区、时间、指标筛选。地区可选：全部、华东、华北、华南、华西。','http://localhost:8080/api/test/sales/report','POST','application/json',NULL,0,0,1,1,'$.data','bar',NULL,NULL,5,300,'system','2026-05-06 16:31:20',NULL,'2026-06-09 19:14:41',1),
(2,'get_operation_report','发展量报表查询','发展量报表查询','http://localhost:8080/api/test/sales/report','POST','application/json',NULL,0,0,1,1,'$.data','table',NULL,NULL,5,0,NULL,'2026-06-09 18:26:05',NULL,'2026-06-09 19:14:39',1),
(3,'query_kpi_cards','政企商机KPI指标卡片','查询政企商机看板顶部门户的4个KPI指标卡片数据，包括：签约合同数量+环比、签约合同金额+环比、商机数量+环比、商机金额+环比。日期范围固定为当年1月1日至昨天(自动计算)，无需传入。入参只有areaCode(地市编码)。返回结构包含QY(签约数据)和SJ(商机数据)两部分。','https://wisdom.loc.zj186.com:9998/prod-api/asiainfo_micro/dmservice/zq_bussness/titleInfo','POST','application/json',NULL,0,0,1,2,'$.data','summary',NULL,'{"version": "1.0","dataPath": "$.data","fields": [{"field": "TOTAL_COUNT", "label": "数量", "type": "metric", "format": "#,##0"},{"field": "ARRAIR_AMOUNT", "label": "签约金额(万元)", "type": "metric", "format": "#,##0.00"},{"field": "LAST_TOTAL_COUNT", "label": "数量同比(%)", "type": "metric", "format": "0.00"},{"field": "LAST_ARRAIR_AMOUNT", "label": "金额同比(%)", "type": "metric", "format": "0.00"},{"field": "EXPECT_CONTRACT_MONEY", "label": "预计签约金额(万元)", "type": "metric", "format": "#,##0.00"},{"field": "LAST_EXPECT_CONTRACT_MONEY", "label": "预计金额同比(%)", "type": "metric", "format": "0.00"}],"displayHints": {"defaultChartType": "card","groupFields": ["QY", "SJ"],"groupLabels": {"QY": "签约", "SJ": "商机"}}}',30,60,'system','2026-06-10 20:45:55',NULL,'2026-06-12 16:49:44',1),
(4,'query_opportunity_summary','商机概览聚合查询','查询政企商机概览数据，按地市聚合返回。支持按时间范围、业务维度(算网数智/联网通信/国际业务)、行业大类(2G/2B)、主业务类型(多选)、客户行业、金额范围筛选。返回各地市的：商机数量、商机金额(万元)、本年签约数量、本年签约金额(万元)、商机转化数量、转化金额(万元)、亿级商机数量、千万级商机数量、商机金额同比(%)、累计拜访次数、平均拜访次数。','https://wisdom.loc.zj186.com:9998/prod-api/asiainfo_micro/dmservice/zq_bussness/oppoSummarize','POST','application/json',NULL,0,0,1,2,'$.data','table',NULL,NULL,30,60,'system','2026-06-10 20:46:37',NULL,'2026-06-11 16:56:53',1),
(5,'query_sign_summary','签约概览聚合查询','查询政企签约概览数据，按地市或区县聚合返回。支持按时间范围、业务类型(数科集成/联通云/数据服务/数智应用/数据中心/联网通信)、客户行业、金额范围筛选。返回各地市/区县的：签约数量、签约金额(万元)、签约金额同比(%)、签约金额完成率(%)、亿级合同数量(>=10000万)、千万级合同数量(1000~10000万)、百万级合同数量(100~1000万)、签约前置商机比例(%)、年化签约金额(万元)。','https://wisdom.loc.zj186.com:9998/prod-api/asiainfo_micro/dmservice/zq_bussness/signSummarize','POST','application/json',NULL,0,0,1,2,'$.data','table',NULL,'{"version":"1.0","dataPath":"$.data","fields":[{"field":"AREA_NAME","label":"地市名称","type":"string"},{"field":"TOTAL_COUNT","label":"签约数量","type":"number","format":"#,##0"},{"field":"ARRAIR_AMOUNT","label":"签约金额(万元)","type":"currency","format":"#,##0.00"},{"field":"TB_ARRAIR_AMOUNT","label":"签约金额同比","type":"percentage"},{"field":"WCL_ARRAIR_AMOUNT","label":"完成率","type":"percentage"},{"field":"YJ_ARRAIR_AMOUNT","label":"亿级合同数量","type":"number","format":"#,##0"},{"field":"QW_ARRAIR_AMOUNT","label":"千万级合同数量","type":"number","format":"#,##0"},{"field":"BW_ARRAIR_AMOUNT","label":"百万级合同数量","type":"number","format":"#,##0"},{"field":"PRE_OPPO","label":"签约前置商机比例","type":"percentage"},{"field":"YEAR_ARRAIR_AMOUNT","label":"年化签约金额(万元)","type":"currency","format":"#,##0.00"},{"field":"YEAR_AMOUNT","label":"年化签约金额(万元)","type":"currency","format":"#,##0.00"}],"displayHints":{"defaultChartType":"table","dimensionField":"","metricField":""}}',30,60,'system','2026-06-10 20:47:14',NULL,'2026-06-12 14:40:43',1),
(6,'query_opportunity_detail','商机明细列表查询','查询政企商机明细列表(分页)，每条记录是一个商机项目。支持按时间范围、地市、区县、金额范围、业务维度、行业大类、主业务类型、客户行业、客户经理、异常商机筛选，并支持排序。返回字段包括：商机编号、名称、创建时间、客户经理、地市、预估金额(万元)、商机状态、主业务类型、客户行业、是否签约、中标金额、合同金额、项目信息、拜访次数、支撑次数、关注状态等。注意：dataType固定传"SJ"(商机)，itrstOa为必填(用户OA，用于查询关注状态，传空则无关注数据)。','https://wisdom.loc.zj186.com:9998/prod-api/asiainfo_micro/dmservice/zq_bussness/oppoListPage','POST','application/json',NULL,0,0,1,2,'$.rows','table','$.total',NULL,30,0,'system','2026-06-10 20:48:13',NULL,'2026-06-11 16:56:58',1),
(7,'query_sign_detail','签约明细列表查询','查询政企签约项目明细列表(分页)，每条记录是一个合同。支持按时间范围、地市、区县、金额范围、业务类型、客户行业、客户经理筛选，并支持排序。返回字段包括：合同编号、合同名称、合同金额(万元)、合同类型、审批日期、业务类型、客户经理、客户名称、客户行业、名单制客户、项目编码、项目名称、关注状态等。注意：dataType固定传"HT"(合同)，itrstOa为必填(用户OA，用于查询关注状态)。','https://wisdom.loc.zj186.com:9998/prod-api/asiainfo_micro/dmservice/zq_bussness/listPage','POST','application/json',NULL,0,0,1,2,'$.rows','table','$.total',NULL,30,0,'system','2026-06-10 20:48:46',NULL,'2026-06-11 16:57:02',1),
(8,'get_trade_cluster_list','客户行业列表查询','查询政企客户行业下拉列表。用于辅助其他查询工具的tradeClusterId参数。无入参。返回行业ID(TRADE_CLUSTER_ID)和行业名称(SF_TRADE_CLUSTER_NAME)。','https://wisdom.loc.zj186.com:9998/prod-api/asiainfo_micro/dmservice/zq_bussness/getCustomer','GET','application/json',NULL,0,0,1,2,'$.data','table',NULL,NULL,10,3600,'system','2026-06-10 20:52:24',NULL,'2026-06-11 16:57:04',1),
(9,'get_business_type_list','商机主业务类型列表查询','查询商机主业务类型下拉列表。用于辅助query_opportunity_summary的oppoTypes参数。可选入参svcType(业务维度过滤，如"算网数智"/"联网通信"/"国际业务")。返回业务类型名称列表(TYPE_NAME)。','https://wisdom.loc.zj186.com:9998/prod-api/asiainfo_micro/dmservice/zq_bussness/getBusinessType','GET','application/json',NULL,0,0,1,2,'$.data','table',NULL,NULL,10,3600,'system','2026-06-10 20:52:29',NULL,'2026-06-11 16:57:08',1);
